package com.tekwatt.firmware.service;import com.tekwatt.firmware.dto.*;import com.tekwatt.firmware.entity.*;import com.tekwatt.firmware.repository.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.client.*;import org.springframework.web.server.ResponseStatusException;@Service@Transactional public class FirmwareService{private final FirmwarePackageRepository packages;private final FirmwareUpdateJobRepository jobs;private final RestClient ocpp;public FirmwareService(FirmwarePackageRepository p,FirmwareUpdateJobRepository j,RestClient.Builder builder,@Value("${tekwatt.ocpp.gateway-url:http://localhost:8094}")String url){packages=p;jobs=j;ocpp=builder.baseUrl(url).build();}public FirmwarePackage createPackage(FirmwarePackageRequest r){if(packages.existsByVendorIgnoreCaseAndModelIgnoreCaseAndVersion(r.vendor(),r.model(),r.version()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Firmware version already exists");return packages.save(new FirmwarePackage(r.vendor(),r.model(),r.version(),r.downloadUrl(),r.checksum(),r.checksumAlgorithm(),r.signature(),r.fileSizeBytes()));}@Transactional(readOnly=true)public List<FirmwarePackage>packages(){return packages.findAll();}@Transactional(readOnly=true)public FirmwarePackage packageById(UUID id){return packages.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Firmware package not found"));}public FirmwareUpdateJob createJob(CreateUpdateJobRequest r){FirmwarePackage p=packageById(r.firmwarePackageId());if(!p.getActive())throw new ResponseStatusException(HttpStatus.CONFLICT,"Firmware package is inactive");return jobs.save(new FirmwareUpdateJob(r.tenantId(),r.chargerId(),r.firmwarePackageId(),r.ocppVersion(),r.scheduledAt()));}@Transactional(readOnly=true)public FirmwareUpdateJob job(UUID id){return jobs.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Update job not found"));}@Transactional(readOnly=true)public List<FirmwareUpdateJob>jobs(UUID tenantId){return jobs.findAllByTenantIdOrderByCreatedAtDesc(tenantId);}public FirmwareUpdateJob status(UUID id,UpdateJobStatusRequest r){FirmwareUpdateJob j=job(id);j.update(r.status(),r.statusInfo());return j;}public FirmwareUpdateJob dispatch(UUID id){FirmwareUpdateJob j=job(id);if(j.getStatus()!=UpdateStatus.SCHEDULED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only scheduled jobs can be dispatched");FirmwarePackage p=packageById(j.getFirmwarePackageId());Map<String,Object>body=new LinkedHashMap<>();body.put("jobId",j.getId());body.put("stationId",j.getChargerId().toString());body.put("ocppVersion",j.getOcppVersion());body.put("location",p.getDownloadUrl());body.put("retrieveDate",j.getScheduledAt());body.put("checksum",p.getChecksum());body.put("signature",p.getSignature());try{ocpp.post().uri("/api/v1/ocpp/commands/firmware").body(body).retrieve().toBodilessEntity();}catch(RestClientResponseException e){throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"OCPP gateway rejected command: "+e.getResponseBodyAsString());}catch(ResourceAccessException e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"OCPP gateway is unavailable");}j.update(UpdateStatus.DOWNLOADING,"UpdateFirmware command sent");return j;}public FirmwareUpdateJob callback(FirmwareStatusCallback r){FirmwareUpdateJob j=jobs.findTopByChargerIdOrderByCreatedAtDesc(r.chargerId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"No firmware job for charger"));j.update(map(r.status()),r.statusInfo()==null?r.status():r.statusInfo());return j;}private UpdateStatus map(String s){return switch(s){case"Downloading"->UpdateStatus.DOWNLOADING;case"Downloaded"->UpdateStatus.DOWNLOADED;case"Installing"->UpdateStatus.INSTALLING;case"Installed"->UpdateStatus.INSTALLED;case"DownloadFailed","InvalidSignature","SignatureVerified"->UpdateStatus.DOWNLOAD_FAILED;case"InstallationFailed","InstallRebooting","InstallScheduled","InstallVerificationFailed"->UpdateStatus.INSTALLATION_FAILED;default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported firmware status: "+s);};}}
